  `allow_trade` enum('0','1') NOT NULL DEFAULT '1',
  `allow_marketplace_sell` enum('0','1') NOT NULL DEFAULT '1',
  `allow_gift` enum('0','1') NOT NULL DEFAULT '1',
  `allow_inventory_stack` enum('0','1') NOT NULL DEFAULT '1',
  `interaction_type` varchar(25) NOT NULL DEFAULT 'default',
  `interaction_modes_count` int(11) NOT NULL DEFAULT 1,
  `vending_ids` varchar(255) NOT NULL DEFAULT '0',
  `height_adjustable` varchar(50) NOT NULL DEFAULT '0',
  `effect_id` int(3) NOT NULL DEFAULT 0,
  `wired_id` int(11) NOT NULL DEFAULT 0,
  `is_rare` enum('0','1') NOT NULL DEFAULT '0',
  `clothing_id` int(11) NOT NULL DEFAULT 0,
  `extra_rot` enum('0','1') NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `id` (`id`) USING BTREE,
  KEY `sprite_id` (`sprite_id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=1000000109 DEFAULT CHARSET=latin1;

-- ----------------------------
-- Records of furniture
-- ----------------------------

-- ----------------------------
-- Table structure for games_config
-- ----------------------------
DROP TABLE IF EXISTS `games_config`;
CREATE TABLE `games_config` (
  `id` int(11) NOT NULL DEFAULT 0,
  `name` varchar(25) NOT NULL DEFAULT '',
  `colour_one` varchar(25) NOT NULL DEFAULT '',
  `colour_two` varchar(25) NOT NULL DEFAULT '',
  `resource_path` varchar(125) NOT NULL,
  `string_three` varchar(25) NOT NULL DEFAULT '',
  `game_swf` varchar(255) NOT NULL DEFAULT '',
  `game_assets` varchar(255) NOT NULL DEFAULT '',
  `game_server_host` varchar(25) NOT NULL DEFAULT '',
  `game_server_port` varchar(25) NOT NULL DEFAULT '',
  `socket_policy_port` varchar(25) NOT NULL DEFAULT '',
  `game_enabled` enum('0','1') DEFAULT '1',
  `last_reset` double DEFAULT 0,
  PRIMARY KEY (`id`),
  UNIQUE KEY `id` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=latin1;

-- ----------------------------
-- Records of games_config
-- ----------------------------

-- ----------------------------
-- Table structure for games_fastfood_objects
-- ----------------------------
DROP TABLE IF EXISTS `games_fastfood_objects`;
CREATE TABLE `games_fastfood_objects` (
  `ObjectName` varchar(25) NOT NULL DEFAULT '',
  `ObjectType` enum('missile','bigparachute','shield') NOT NULL,
  `ObjectPrice` int(11) NOT NULL DEFAULT 0,
  `ObjectBundle` int(11) NOT NULL DEFAULT 1,
  PRIMARY KEY (`ObjectName`)
) ENGINE=InnoDB DEFAULT CHARSET=latin1;

-- ----------------------------
-- Records of games_fastfood_objects
-- ----------------------------

-- ----------------------------
-- Table structure for games_fastfood_plates
-- ----------------------------
DROP TABLE IF EXISTS `games_fastfood_plates`;
CREATE TABLE `games_fastfood_plates` (
  `PlateId` int(200) NOT NULL AUTO_INCREMENT,
  `PlateSomething` varchar(200) NOT NULL,
  `PlateDropSpeed` varchar(200) NOT NULL DEFAULT '0.0000',
  `PlateParachuteSpeed` varchar(200) NOT NULL DEFAULT '0.0000',
  `PlateBigParachuteSpeed` varchar(200) NOT NULL DEFAULT '0.0000',
  `PlatePrepTime` int(11) NOT NULL DEFAULT 0,
  PRIMARY KEY (`PlateId`)
) ENGINE=InnoDB AUTO_INCREMENT=4094 DEFAULT CHARSET=latin1;

-- ----------------------------
-- Records of games_fastfood_plates
-- ----------------------------

-- ----------------------------
-- Table structure for groups_forums_posts
-- ----------------------------
DROP TABLE IF EXISTS `groups_forums_posts`;
CREATE TABLE `groups_forums_posts` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `parent_id` int(11) unsigned NOT NULL DEFAULT 0,
  `group_id` int(11) unsigned NOT NULL,
  `timestamp` int(11) NOT NULL,
  `pinned` enum('0','1') NOT NULL DEFAULT '0',
  `locked` enum('0','1') NOT NULL DEFAULT '0',
  `hidden` enum('0','1') NOT NULL DEFAULT '0',
  `poster_id` int(11) unsigned NOT NULL,
  `poster_name` varchar(255) NOT NULL,
  `poster_look` varchar(1024) NOT NULL,
  `subject` varchar(1024) NOT NULL,
  `post_content` text NOT NULL,
  `post_hider` int(11) NOT NULL DEFAULT 0,
  PRIMARY KEY (`id`),
  UNIQUE KEY `id` (`id`)
) ENGINE=MyISAM AUTO_INCREMENT=55 DEFAULT CHARSET=utf8;

