INSERT INTO `moderation_preset_action_messages` VALUES ('1', '1', 'CFH Abuse', 'Do not abuse the Call for Help (CFH) system; it should be used during emergency purposes only.', '0', '0', '0', '0', '');
INSERT INTO `moderation_preset_action_messages` VALUES ('2', '1', 'Advertising', ' Do not advertise other Habbo Retros; hotel links or purposely mentioning the name of another hotel\r\nwith the intentions of advertising is strictly forbidden. In addition, generally objectionable websites are not permitted.', '0', '0', '0', '0', '');
INSERT INTO `moderation_preset_action_messages` VALUES ('3', '1', 'Scamming', 'Do not attempt to or scam credits or furniture from other users through betting, gaming, or trading.', '0', '0', '0', '0', '');
INSERT INTO `moderation_preset_action_messages` VALUES ('4', '1', 'Bullying', 'Do not bully, harass, or abuse other users; avoid violent or aggressive behaviour.', '0', '0', '0', '0', '');
INSERT INTO `moderation_preset_action_messages` VALUES ('5', '4', 'Personal Info', 'Do not disclose any personal information of another user (e.g., address, IP Address, phone number, school) without their consent.', '0', '0', '0', '0', '');
INSERT INTO `moderation_preset_action_messages` VALUES ('6', '4', 'Spamming', 'Do not excessively repeat identical or similar statements (spamming).', '0', '0', '0', '0', '');
INSERT INTO `moderation_preset_action_messages` VALUES ('7', '4', 'Sexual/Inappropriate', 'Users are to not participate in any sexual, inappropriate, or generally objective acts towards other users without their prior consent.', '0', '0', '0', '0', '');
INSERT INTO `moderation_preset_action_messages` VALUES ('8', '4', 'DDoS', 'Do not attempt to or successfully harm a userÔÇÖs home internet connection.', '0', '0', '0', '0', '');
INSERT INTO `moderation_preset_action_messages` VALUES ('9', '2', 'Giveaway/sell/trade account', 'Do not attempt to or give away, sell, or trade your Habboon Hotel account and/or Habboon items for virtual items from another game, accounts from another game, cash, or vice versa without permission from an Administrator.', '0', '0', '0', '0', '');
INSERT INTO `moderation_preset_action_messages` VALUES ('10', '2', 'Offensive usernames', 'Do not create a username with an offensive name that is insulting, racist, harassing, or generally objectionable.', '0', '0', '0', '0', '');
INSERT INTO `moderation_preset_action_messages` VALUES ('11', '2', 'IP ban evading', 'Do not evade an IP Address ban.', '0', '0', '0', '0', '');
INSERT INTO `moderation_preset_action_messages` VALUES ('12', '2', 'Account Sharing', 'Do not share your account with other users.', '0', '0', '0', '0', '');
INSERT INTO `moderation_preset_action_messages` VALUES ('13', '5', 'Threats/Hacks', 'Do not threaten to, attempt to, or hack other users\' accounts', '0', '0', '0', '0', '');
INSERT INTO `moderation_preset_action_messages` VALUES ('14', '5', 'Multiple Accounts', 'Do not create multiple accounts for the purpose of taking an advantage over gaining more in-game currency and/or rares of any kind.', '0', '0', '0', '0', '');
INSERT INTO `moderation_preset_action_messages` VALUES ('15', '3', 'Exploit Abusing', 'Do not attempt to or exploit errors of Habboon Hotel; report it to the Administration immediately.', '0', '0', '0', '0', '');
INSERT INTO `moderation_preset_action_messages` VALUES ('16', '3', 'Chargebacks', 'Do not attempt to or refund your VIP Membership or donation to Habboon Hotel at any given time; all payments are final.', '0', '0', '0', '0', '');
INSERT INTO `moderation_preset_action_messages` VALUES ('17', '6', 'Misleading Info', 'Do not intentionally give wrong or misleading information to staff members in reports about rule violations, complaints, bug reports, or support requests.', '0', '0', '0', '0', '');
INSERT INTO `moderation_preset_action_messages` VALUES ('18', '3', 'False statements', 'Do not make false statements against Habboon Hotel or any other part of its services.', '0', '0', '0', '0', '');
INSERT INTO `moderation_preset_action_messages` VALUES ('19', '3', 'Impersonation', 'Do not pretend to be a representative of Habboon Hotel or claim to have their powers.', '0', '0', '0', '0', '');
INSERT INTO `moderation_preset_action_messages` VALUES ('20', '6', 'Threatening Habboon', 'Do not threaten to, attempt to, or use any scripts or third party software to enter, disrupt, or modify Habboon Hotel.', '0', '0', '0', '0', '');
