INSERT INTO `room_items_whisper_tile` VALUES ('85999', 'This is the \'guns + fists\' SoloQueue Arena.');
INSERT INTO `room_items_whisper_tile` VALUES ('86000', 'This is the \'guns + fists\' SoloQueue Arena.');
