INSERT INTO `room_items_whisper_tile` VALUES ('89254', 'Welcome to the Police Training room!');
INSERT INTO `room_items_whisper_tile` VALUES ('89405', '');
INSERT INTO `room_items_whisper_tile` VALUES ('107760', '');
INSERT INTO `room_items_whisper_tile` VALUES ('142708', 'You can workout your stamina here! The benefit of stamina is to raise your max energy by +5 per stamina level.');
INSERT INTO `room_items_whisper_tile` VALUES ('142709', 'You can workout your strength here! The benefit of strength is to do more damage when you\'re fighting someone using fists.');
